def evalRPN(tokens: list[str]) -> int:
    items = list(tokens)
    def is_op(token: str) -> bool:
        return token in ('+', '-', '*', '/')
    while len(items) > 1:
        op_idx = -1
        for i, tok in enumerate(items):
            if is_op(tok):
                op_idx = i
                break
        if op_idx < 1:
            break
        a_raw = items[op_idx - 2]
        b_raw = items[op_idx - 1]
        try:
            a = int(a_raw)
            b = int(b_raw)
        except (ValueError, TypeError):
            return None
        op = items[op_idx]
        if op == '+':
            value = a + b
        elif op == '-':
            value = a - b
        elif op == '*':
            value = a * b
        else:
            if b == 0:
                return None
            value = int(a / b)
        items[op_idx - 2:op_idx + 1] = [str(value)]
    if not items:
        return 0
    try:
        return int(items[-1])
    except ValueError:
        return None

